        D(n=35, slug="35-ridgeway-fuel-tune-notes", doc_id="RDW-MTG-2022-024", title="Diesel fuel system tune-up notes, September 8", subtitle="Filters, air in fuel, ticket RDW-2344", doc_type="Meeting notes", form_type="Other", org=RID, role=HELP, date="2022-09-08", kicker="Ridgeway Diesel  ·  Fuel  ·  RDW-2344", ticket="RDW-2344", host="bay-03.ridgeway.internal", hosts=["bay-03.ridgeway.internal", "shop.ridgeway.internal", "parts.ridgeway.internal"], tickets=["RDW-MTG-2022-024", "RDW-2344", "RDW-SOP-2022-011"], people="ridgeway", requester="Hank Morel", quote="If we do not prime after a filter, we will crank it dead and then blame the starter.", quote_attr="Hank Morel, parts, September 8", decision="Replace both filters as a pair. Prime. No long crank. Air in fuel is a leak, not a 'needs more cranking.'", reject="crank until it catches after a filter", reject_why="August 30 starter cooked after 28 seconds of crank. Filter was dry. Prime is 90 seconds of work.", current="One filter, crank, hope", lock="pair of filters, prime, no long crank", nums=dict(seconds=28, prime=90, filters=2, weeks=2, starter=1, air=1, pair=1, hope=0), form_description="Notes for Ridgeway Diesel fuel-system tune-ups: paired filters, prime, refusing long-crank after a dry filter."),
